NEW_FILES = []

import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))


def fail(msg):
    print(msg)
    print("NOTHING was written. Undo is not needed.")
    sys.exit(1)


def main():
    for rel, _ in NEW_FILES:
        if os.path.exists(os.path.join(HERE, *rel.split("/"))):
            fail("ERROR: %s already exists; this patch has run." % rel)
    staged = []
    for rel, edits in EDITS:
        path = os.path.join(HERE, *rel.split("/"))
        if not os.path.isfile(path):
            fail("ERROR: not found: %s -- is this file in the right folder?"
                 % path)
        raw = open(path, "rb").read()
        crlf = b"\r\n" in raw
        text = raw.replace(b"\r\n", b"\n").decode("utf-8")
        for k, (old, new) in enumerate(edits):
            n = text.count(old)
            if n != 1:
                if text.count(new) == 1:
                    fail("ERROR: %s already carries edit %d of %d; this "
                         "patch has run." % (rel, k + 1, len(edits)))
                fail("ANCHOR FAIL in %s, edit %d of %d: expected 1 match, "
                     "found %d" % (rel, k + 1, len(edits), n))
            text = text.replace(old, new)
        staged.append((rel, path, text, crlf, len(edits)))
    for rel, path, text, crlf, n in staged:
        open(path, "wb").write(text.encode("utf-8"))
        print("ok  %s (%d edits)" % (rel, n))
        if crlf:
            print("note: %s was CRLF in the working copy; written LF" % rel)
        bad = sum(1 for c in text if ord(c) > 127)
        if bad:
            print("note: %s holds %d non-ASCII character(s) this patch did "
                  "not add" % (rel, bad))
    for rel, content in NEW_FILES:
        full = os.path.join(HERE, *rel.split("/"))
        d = os.path.dirname(full)
        if d and not os.path.isdir(d):
            os.makedirs(d)
        open(full, "wb").write(content.encode("utf-8"))
        print("ok  %s: new" % rel)
    print(DONE % (len(staged), len(NEW_FILES)))
    cache_report()


def cache_report():
    """Read data/orbit_paths.json and say whether the path cached for
    C/2025_K1 is this comet: compare it with piece B's cached path at the
    dates both hold. Writes nothing."""
    import json
    import math
    path = os.path.join(HERE, "data", "orbit_paths.json")
    print("")
    print("CACHED PATH CHECK, C/2025_K1 (reads data/orbit_paths.json; "
          "changes nothing)")
    if not os.path.isfile(path):
        print("  No data/orbit_paths.json here: nothing is cached to check.")
        return
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception as exc:
        print("  Could not read the cache (%s): not checked." % exc)
        return
    pre = "C/2025_K1_"
    keys = sorted(k for k in data if k.startswith(pre))
    if not keys:
        print("  No path is cached for C/2025_K1: the orrery fetches it by "
              "the new id when it is first plotted. Nothing to do.")
        return

    def points(entry):
        out = {}
        dp = entry.get("data_points") if isinstance(entry, dict) else None
        if not isinstance(dp, dict):
            return out
        for d, p in dp.items():
            try:
                out[str(d)[:10]] = (float(p["x"]), float(p["y"]),
                                    float(p["z"]))
            except (KeyError, TypeError, ValueError):
                pass
        return out

    for key in keys:
        centre = key[len(pre):]
        mine = points(data[key])
        meta = data[key].get("metadata", {}) if isinstance(data[key], dict) else {}
        dates = sorted(mine)
        print("  %s: %d points, %s to %s, last updated %s" % (
            key, len(dates), dates[0] if dates else "-",
            dates[-1] if dates else "-", meta.get("last_updated", "-")))
        other = data.get("C/2025_K1-B_" + centre)
        if other is None:
            print("    No path cached for piece B around %s, so it cannot be "
                  "compared." % centre)
            continue
        theirs = points(other)
        shared = sorted(set(mine) & set(theirs))
        if not shared:
            print("    Piece B's cached path shares no date with it, so it "
                  "cannot be compared.")
            continue
        far = []
        worst = (0.0, None)
        for d in shared:
            a, b = mine[d], theirs[d]
            dist = math.sqrt(sum((a[i] - b[i]) ** 2 for i in range(3)))
            if dist > worst[0]:
                worst = (dist, d)
            if dist > 0.1:
                far.append(d)
        print("    Against piece B on %d shared dates (%s to %s): at most "
              "%.4f AU apart (on %s)." % (len(shared), shared[0],
                                          shared[-1], worst[0], worst[1]))
        if not far:
            print("    VERDICT: the cached path is this comet (within 0.1 AU "
                  "of piece B throughout). Nothing to do.")
        else:
            print("    VERDICT: on %d of those dates, from %s to %s, the cached "
                  "path is more than 0.1 AU from piece B: it holds another "
                  "body's positions there. Paste this into the chat before "
                  "plotting C/2025 K1." % (len(far), far[0], far[-1]))


if __name__ == "__main__":
    main()
